-- Editorial/demo inventory: original PEANUTZIN copy; factual items retain source URLs.
on conflict(slug) do update set title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,category=excluded.category,status=excluded.status,featured=excluded.featured,hero_image_path=excluded.hero_image_path,hero_image_alt=excluded.hero_image_alt,published_at=excluded.published_at,source_name=excluded.source_name,source_url=excluded.source_url;

-- Third-party records are preview-only and do not imply a supply relationship.
on conflict(slug) do update set title=excluded.title,author=excluded.author,description=excluded.description,price_cents=excluded.price_cents,publisher=excluded.publisher,language=excluded.language,genre=excluded.genre,format=excluded.format,ebook_price_cents=excluded.ebook_price_cents,catalogue_type=excluded.catalogue_type,independent_publisher=excluded.independent_publisher,emerging_author=excluded.emerging_author,preview_only=excluded.preview_only;
